public int findLargestSubstring(List<String> strings) {
    int largestSubstring = 0;
    for (String string : strings) {
        int substringLength = 0;
        for (int i = 0; i < string.length() - 1; i++) {
            for (int j = i + 1; j < string.length(); j++) {
                if (string.substring(i, j).equals(string.substring(string.length() - j - 1, string.length() - i - 1))) {
                    substringLength = Math.max(substringLength, j - i);
                }
            }
        }
