public int findLargestSubstring(List<String> strings) {
    // list to store the appearances of each string
    List<Integer> appearances = new ArrayList<>();

    // create a set to store the unique strings
    Set<String> uniqueStrings = new HashSet<>(strings);

    // loop over the unique strings
    for (String uniqueString : uniqueStrings) {
        // initialize the appearance count for the current string
        int count = 0;

        // loop over the original strings
        for (String string : strings) {
            // check if the current string is a substring of the original string
            if (string.contains(uniqueString)) {
                // if the current string is a substring, increment the appearance count
                count++;
            }
        }

        // add the appearance count for the current string to the list
        appearances.add(count);
    }

    // find the largest appearance count
    int largestAppearance = appearances.stream().max(Integer::compareTo).get();

    // find the corresponding string with the largest appearance count
    String largestString = "";
    for (int i = 0; i < strings.size(); i++) {
        if (appearances.get(i) == largestAppearance) {
            largestString = strings.get(i);
            break;
        }
    }

    // return the length of the largest string
    return largestString.length();
}
