    for (int row = 0; row < grid.length; row++) {
        for (int col = 0; col < grid[row].length; col++) {
            if (grid[row][col] == '@') {
                numDeposits++;
                for (int i = row + 1; i < grid.length; i++) {
                    for (int j = col + 1; j < grid[i].length; j++) {
                        if (grid[i][j] == '@') {
