public static int maxRegions(int N) {
    // Ensure input is valid
    if (N < 0) {
        throw new IllegalArgumentException("Illegal input: " + N);
    }
    // Initialize output
    int maxRegions = 2;
    // Iterate over N triangles
    for (int i = 0; i < N; i++) {
        // Compute the number of regions for the ith triangle
        int numRegions = Integer.highestOneBit(i) * 2;
