public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("Invalid input");
    }

    char[] buf = new char[n];

    for (int i = 0; i < n; i++) {
        buf[i] = (char) ((i + 1) + 'a' - 1);
    }

    for (int i = 0; i < n - 1; i++) {
        int pos = i + 1;
        while (pos < n && buf[pos] - buf[i] < k) {
            pos++;
        }
        if (pos == n) {
            return null;
        }
        char c = (char) ((buf[pos] + 'a' - 1) - (buf[i] + 'a' - 1) + k);
        buf[i] = (char) ((buf[i] - 1) + (c - 'a' + 1));
        k -= (buf[pos] - buf[i]);
    }

    return new String(buf);
}
