    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                // horizontal
                maxLength = Math.max(maxLength, getMaxLength(mat, i, j, 0, 1));
                // vertical
                maxLength = Math.max(maxLength, getMaxLength(mat, i, j, 1, 0));
                // diagonal
                maxLength = Math.max(maxLength, getMaxLength(mat, i, j, 1, 1));
                // anti-diagonal
                maxLength = Math.max(maxLength, getMaxLength(mat, i, j, -1, 1));
            }
        }
    }
    return maxLength;
}

private static int getMaxLength(int[][] mat, int i, int j, int di, int dj) {
    int maxLength = 0;
    for (int k = 1; i + k * di >= 0 && j + k * dj >= 0 && i + k * di < mat.length && j + k * dj < mat[i].length; k++) {
        if (mat[i + k * di][j + k * dj] == 1) {
            maxLength++;
        } else {
            break;
        }
    }
    return maxLength;
}
