public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String numStr = Integer.toString(n);
    int numStrLength = numStr.length();
    int[] numArr = new int[numStrLength];
    for (int i = 0; i < numStrLength; i++) {
        numArr[i] = Character.digit(numStr.charAt(i), 10);
    }
    int smallestNum = Integer.valueOf(numStr);
    int currentNum = 0;
    // sort the digits in the input number
    Arrays.sort(numArr);
    do {
        // concatenate the sorted digits to form a new number
        currentNum = Integer.valueOf(convertArrayToString(numArr));
        if (currentNum > n) {
            // if the new number is greater than the input number, return the previous number
            return smallestNum;
        }
        smallestNum = currentNum;
    } while (nextPermutation(numArr));
    // if no permutation can form a number greater than the input number, return -1
    return -1;
}

/**
