/**
 * Generates the next permutation of a given integer array in place
 * @param arr - an integer array
 * @return true if the next permutation exists, false otherwise
 */
private static boolean nextPermutation(int[] arr) {
    int i = arr.length - 1;
    while (i > 0 && arr[i] > arr[i - 1]) {
        i--;
    }
    if (i <= 0) return false;
    int j = arr.length - 1;
    while(arr[j] <= arr[i - 1]) {
        j--;
    }
    swap(arr, i - 1, j);
    rev(arr, i);
    return true;
}

/**
 * Swaps two elements in an integer array
 * @param arr - an integer array
 * @param i - the first index
 * @param j - the second index
 */
private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

/**
 * Reverses an integer array given a starting index
 * @param arr - an integer array
 * @param i - the starting index
 */
private static void rev(int[] arr, int i) {
    int j = arr.length - 1;
    while (i < j) {
        swap(arr, i, j);
        i++;
        j--;
    }
}

