public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    for (int i = 1; i * i <= n; i++) {
        int currSquares = 1;
        while (n - i * i >= 0) {
            n -= i * i;
            currSquares++;
        }
        minSquares = Math.min(minSquares, currSquares);
    }
    return minSquares;
}

